import type { ComponentType, CSSProperties, ReactNode } from "react";
import {
  SiLinear,
  SiLinearHex,
  SiStripe,
  SiStripeHex,
} from "@icons-pack/react-simple-icons";

/**
 * Brand marks rendered with their official colors. Multi-color / colored
 * marks are vendored from lobe-icons (MIT, https://github.com/lobehub/lobe-icons);
 * Composio's is from logos.composio.dev. Brands whose mark is black
 * (OpenAI, Ollama, LM Studio, GitHub, Notion) use currentColor so they stay
 * visible in dark mode.
 */
export type BrandIcon = ComponentType<{
  className?: string;
  style?: CSSProperties;
}>;

interface SvgProps {
  className?: string;
  style?: CSSProperties;
  viewBox?: string;
  fill?: string;
  children: ReactNode;
}

const Svg = ({
  className,
  style,
  viewBox = "0 0 24 24",
  fill = "currentColor",
  children,
}: SvgProps) => (
  <svg
    className={className}
    style={style}
    width="1em"
    height="1em"
    viewBox={viewBox}
    fill={fill}
    xmlns="http://www.w3.org/2000/svg"
    aria-hidden
  >
    {children}
  </svg>
);

